#!/usr/bin/env python3
"""Word documents matching exact AES-256 / OAEP SHA-256 NIST-generated coverage."""
from pathlib import Path
import json
from word_document import write_docx
ROOT=Path(__file__).resolve().parents[1];DOCS=ROOT/'docs'
BASE=ROOT/'src/test/resources/nist-acvp'
PREFIX='src/main/java/vn/edu/atbm/mssv1150080127/'
def main():
 manifest=json.loads((BASE/'manifest.json').read_text())
 origin=json.loads((BASE/'generated-kts-sha256/origin.json').read_text())
 quality=manifest['quality']
 counts=quality['aes_counts']
 architecture=[['File','Vai trò'],['crypto/AesGcm.java','AES-GCM dùng chung cho demo và vector.'],['crypto/RsaKeyManager.java','wrapKey/unwrapKey thực tế, AES32 byte, OAEP SHA256, label rỗng.'],['crypto/RsaOaep.java','Primitive OAEP được RsaKeyManager gọi.'],['crypto/SecurePackageEngine.java','Dựng/đọc gói, sinh khóa/nonce, gọi AES và RSA dùng chung.'],['util/NistAcvpParser.java','Đọc dữ liệu AES, kiểm tra trường/độ dài.'],['util/AesGcmVectorVerifier.java','So kết quả AES với đáp án NIST GenVal.'],['util/KtsOaepVectors.java','Đọc KTS đúng256; gọi unwrapKey thật; tạo response bằng wrapKey/unwrapKey thật để NIST validator chấm.'],['util/ReferenceChecks.java','Thực thi140 ca đối chiếu trên web.']]
 write_docx(ROOT/'README.docx','Hướng dẫn chạy — dữ liệu NIST đúng cấu hình demo',[
 ('1. Trạng thái',['Demo dùng AES-256-GCM, RSA-2048 OAEP SHA-256/MGF1-SHA-256, label rỗng, khóa AES32 byte. Dữ liệu tham chiếu hiện khớp chính cấu hình này. Bộ mẫu128/SHA512 và CAVP mirror cũ đã được thay thế.','Dữ liệu mới do công cụ NIST GenVal sinh cục bộ từ mã nguồn ACVP-Server ở commit cố định; không nói đây là file mẫu tải sẵn từ GitHub, không phải NIST trực tiếp cấp chứng nhận.']),
 ('2. Chạy ứng dụng và kiểm thử',['Cần JDK21, Maven3.9+, Python3.9+ (standard library), openssl CLI tương thích pkeyutl. Dependency Java khóa trong pom.xml.\npython3 scripts/verify_data.py\nmvn clean test\npython3 scripts/demo.py init\npython3 scripts/demo.py run','Mở http://127.0.0.1:8080. Tab trao đổi tệp mô phỏng cả hai bên. Tab bằng chứng tính140 ca mới:120 AES256 và20 giải bọc OAEP256. Mở hàng để xem source/expected/actual. Dừng bằng Ctrl+C.','Khoá lưu PKCS#12 có mật khẩu; nạp lại khi restart. Xem docs/03_Hoan_thien_va_thuyet_trinh.md để quản lý khoá và dùng chữ ký. Không dùng dữ liệu nhạy cảm; đây chưa là E2EE chống server. Chỉ chạy loopback.']),
 ('3. Bộ bằng chứng giữa kỳ',['sh scripts/run_midterm.sh','Tạo artifacts/run-<UTC> với raw.csv,summary.csv,RESULTS.docx,JUnit XML/log, môi trường và checksum.72 phép đo=3 nguồn giả lập×4 kích thước×2mode×3lần. Không chọn lần nhanh nhất.','JUnit đọc bằng chứng NIST validator đã lưu, kiểm tra hash source để không dùng chứng cứ cũ khi code wrap/unwrap thay đổi. Chạy JUnit không tự khởi động server NIST, không cần cài.NET cho sử dụng bình thường.']),
 ('4. Sinh lại dữ liệu bằng NIST (chỉ khi cần)',['Yêu cầu thêm.NET8/9 SDK, mạng NuGet và cổng loopback. Không cần làm bước này mỗi lần mã hóa. Bản đã sinh được đóng băng trong src/test/resources/nist-acvp/generated-*.','python3 scripts/setup_nist_source.py --destination /tmp/nist-reference\nSau đó build2 project và khởi động Orleans host theo tools/nist-generation/config.json. Chạy:\npython3 scripts/generate_nist_vectors.py --source <nguồn-đã-build>','Công cụ sinh ngẫu nhiên mới, nên các byte khác bản trước là bình thường. registration.json khóa cấu hình; commit khóa mã nguồn. expectedResults/internalProjection do NIST generator tính, không do Java bài tạo.']),
 ('5. Để NIST validator kiểm tra wrap/unwrap mới',['Biên dịch Java trước: mvn compile.\nChạy lớp vn.edu.atbm.mssv1150080127.util.KtsOaepVectors với classpath target/classes và gson2.10.1.jar (Gson có trong Maven cache). Lớp tạo iutResponses.json bằng10 wrapKey và10 unwrapKey thật.','Lệnh macOS/Linux:\njava -cp "target/classes:$HOME/.m2/repository/com/google/code/gson/gson/2.10.1/gson-2.10.1.jar" vn.edu.atbm.mssv1150080127.util.KtsOaepVectors\npython3 scripts/generate_nist_vectors.py --source <nguồn-đã-build> --validate\npython3 scripts/prepare_acvp.py\npython3 scripts/verify_data.py\nmvn clean test','Validator NIST chạy cục bộ phải chấp nhận20 response đúng và từ chối một response cố tình sửa dkm. Script lưu validation.json, negative-validation.json và java-validation-evidence.json. Sau đó tạo lại Word bằng python3 scripts/create_documents.py.']),
 ('6. Tài liệu học và cấu trúc',['docs/01_Lam_chu_kiem_thu_NIST.docx giải thích chuỗi bằng chứng mới. docs/02_Bao_cao_tien_do.docx ghi phạm vi giữa kỳ và giới hạn.',architecture])])
 write_docx(DOCS/'01_Lam_chu_kiem_thu_NIST.docx','Làm chủ kiểm chứng đúng cấu hình với công cụ NIST',[
 ('1. Điều đã thay đổi',['Trước đây: dùng mẫu có sẵn128/SHA512 khác cấu hình demo, bổ sung OpenSSL cho256. Hiện tại: tự cấu hình công cụ NIST sinh đúng AES256-GCM và RSA2048/OAEP SHA256/khóa32byte. Không sửa nhãn của đáp án cũ.','Ba bên cần phân biệt: người làm chọn cấu hình registration; NIST GenVal tạo đề/đáp án; code Java của bài làm bài. Validator NIST cục bộ chấm response. Không tuyên bố đây là validation chính thức của NIST.']),
 ('2. Nguồn gốc và kiểm tra độc lập',['Nguồn công cụ: https://github.com/usnistgov/ACVP-Server/tree/'+manifest['commit'],'Đã build mã nguồn NIST không sửa file.cs, chỉ copy props theo hướng dẫn upstream. Origin ghi commit, phiên bản.NET và hash binary. Cấu hình ở generated-aes256/registration.json và generated-kts-sha256/registration.json. Generated_at KTS: '+origin['generated_at'],'Đáp án không được Java đang kiểm tra tạo ra. Các key/private key trong JSON chỉ là khóa thử công khai để tái lập, tuyệt đối không dùng trong sản xuất. Hash giúp nhận biết thay đổi so với mốc đã ghi; không phải chứng nhận nguồn một mình.']),
 ('3. Theo một ca AES',['Mở src/test/resources/nist-acvp/generated-aes256/internalProjection.json. Group1/tc1 có key256,IV96,tag128. key/iv/aad/pt là đầu vào; ct/tag là đáp án. Hai ký tự hex=1byte.','aes-gcm-sample.json là bản sao nguyên byte của output đó; prepare_acvp.py kiểm tra trùng và giữ đủ120 ca, không chọn theo pass.','Mở '+PREFIX+'util/NistAcvpParser.java: chuyển hex thành byte. Mở AesGcmVectorVerifier.java: expected=ct||tag; actual=AesGcm.encrypt(...). Arrays.equals so byte; khác thì ném lỗi. Decrypt positive so PT; negative phải từ chối.']),
 ('4. Nối đến đúng demo',['Mở '+PREFIX+'crypto/AesGcm.java: chỉ một nơi thực hiện AES/GCM/NoPadding. Sau đó mở SecurePackageEngine.java: pack/unpack gọi chính encrypt/decrypt đó.','AesGcmVectorTest gọi verifier trên120 ca. Thay đổi sai primitive sẽ ảnh hưởng cả demo lẫn vector test. Test gói riêng kiểm tra ứng dụng truyền đúng header, payload và khóa.']),
 ('5. Đúng SHA256 trong phần RSA',['Mở '+PREFIX+'util/KtsOaepVectors.java. cases() bắt buộc RSA2048,hashSHA2-256,emptylabel,l256. actual() dựng private key từ vector, gọi chính RsaKeyManager.unwrapKey và so32 byte với iutK hoặc serverK.20 ca đều đúng cấu hình gói.','Trong generated-kts-sha256: group1 là initiator/bên bọc; group2 responder/bên giải bọc. File internalProjection giữ cả thông tin nội bộ phía server nên có thể kiểm tra thêm giải bọc bản mã tham chiếu ở cả20 ca. Đây là140 ca trên web:120AES+20unwrap.']),
 ('6. Chứng minh cả wrapKey bằng NIST, không chỉ unwrap',['Không so trực tiếp hai ciphertext OAEP vì seed ngẫu nhiên; cùng nội dung vẫn có ciphertext khác. Thay vào đó dùng quy trình validator NIST.','KtsOaepVectors.main sinh10 khóa AES mới và dùng wrapKey thật với public key NIST; gửi iutC và dkm vừa chọn.10 ca responder gọi unwrapKey thật trên serverC. Tất cả ghi iutResponses.json.','NIST GenVal -n internalProjection.json -b iutResponses.json dùng triển khai tham chiếu của NIST để kiểm tra. Với group1, validator giải bản mã Java bằng private key server và so với dkm Java khai báo. Với group2, đối chiếu khóa Java khôi phục với đáp án NIST.','Mở generated-kts-sha256/validation.json: disposition=passed,20 result=passed. Đây là kết quả công cụ NIST chạy cục bộ, không phải chữ PASS do màn hình Java tự ghi.']),
 ('7. Kiểm tra phép chấm không phải luôn PASS',['Script --validate còn sửa một byte dkm của response đầu rồi chạy validator ở thư mục tạm. negative-validation.json phải không passed và có ca failed. Điều này kiểm tra validator phát hiện một kết quả khai báo sai.','java-validation-evidence.json lưu hash response,verdict và3 source: RsaKeyManager,RsaOaep,KtsOaepVectors. JUnit kiểm tra các hash này. Nếu sửa code, phải tạo response và chạy validator lại thay vì dùng chứng cứ cũ.']),
 ('8. Bằng chứng nào cho việc gì?',[[['Bằng chứng','Kết luận trong phạm vi'],['120 vector AES256','Phép mã hóa/giải mã AES-GCM khớp đáp án/thất bại theo kỳ vọng.'],['20 vector OAEP256','unwrapKey thật khôi phục đúng32byte ở đúng cấu hình.'],['NIST validator20 response Java','10 wrap và10 unwrap của code thật phù hợp kiểm tra KTS-OAEP-basic.'],['Negative validator','Một dkm sai bị phát hiện; không chỉ báo thành công vô điều kiện.'],['OpenSSL hai chiều','Bằng chứng độc lập bổ sung; hiện không còn là nguồn duy nhất cho SHA256.'],['SecurePackageTest','Việc đóng/mở gói,header,flags,độ dài,can thiệp và đúng byte.']]]),
 ('9. Điều không nên suy rộng',['Không gọi dữ liệu sinh cục bộ là mẫu tải sẵn NIST. Không gọi kết quả validator cục bộ là chứng nhận do NIST cấp. Không nói mọi lỗi hệ thống đều đã được phát hiện.','NIST không tự biết định dạngSECP. Gói,quản lý khóa và ứng dụng cần test riêng. Mỗi lần web giải mã kiểm tra tag của gói đó; không gửi dữ liệu thật tới NIST hay chạy lại GenVal.']),
 ('10. Lộ trình học trực tiếp',['Mở registration → origin → internalProjection → parser → verifier → primitive → pack/unpack → JUnit. Với RSA, thêm main tạo response → validation.json → negative-validation.json.','Tự giải thích:Ai tạo đáp án?Hàm nào làm bài?Điều kiện nào quyết định sai?Code demo gọi ở đâu?Nếu code đổi, bằng chứng nào hết hiệu lực? Khi chỉ được từng file để trả lời, em đã hiểu thay vì chỉ nhớ một chữ PASS.'])])
 write_docx(DOCS/'02_Bao_cao_tien_do.docx','Báo cáo tiến độ giữa kỳ — kiểm chứng đúng cấu hình',[
 ('1. Phạm vi',['Nguyên mẫu AES256-GCM+RSA2048-OAEP SHA256 để trao đổi tệp. Baseline không nén; biến thể GZIP trước mã hóa. Đóng góp là quy trình,định dạng và kiểm chứng,không phát minh AES/RSA. Paper nằm ngoài đợt này theo quyết định người học; chưa nhận đã hoàn thành tiêu chí dịch/tái lập paper.']),
 ('2. Câu hỏi nghiên cứu',['RQ1:primitive dùng trong demo có khớp nguồn NIST ở đúng cấu hình không? H1:output đúng byte/negative bị từ chối.\nRQ2:toàn gói có bảo toàn dữ liệu và từ chối can thiệp? H2:đúng theo ma trậntest.\nRQ3:GZIP đổi thời gian và kích thước thế nào? H3:phụ thuộc độ nén dữ liệu,không luôn tốt hơn.']),
 ('3. Dữ liệu và provenance',['Dữ liệu sinh bằng NIST GenVal ở commit '+manifest['commit']+'. Không chỉnh source.cs của công cụ. Registration và output/log/origin/hash giữ trong generated-aes256 và generated-kts-sha256.','AES120 ca: '+str(counts)+'. KTS20 ca:10initiator+10responder; RSA2048,OAEP SHA256/MGF1-SHA256,labelrỗng,khóa256bit. Không chọn ca theo output. Không có train/test split vì không huấn luyện. Notice NIST giữ nguyên trong upstream/NIST-NOTICE.txt.','Vòng validation:Java tạo10 wrap/10unwrap,validatorNIST cục bộ chấm20passed;negative control sửa một byte dkm bị từ chối. Lưu sourcehash để ràng buộc chứng cứ với code. Đây không phải chứng nhận CAVP/FIPS chính thức.']),
 ('4. Kiến trúc và gói',[architecture,'Big-endian:SECP4|version1|flags1|wrappedKeyLen2|wrappedKey256|IV12|nameLen2|nameM|ctAndTagLen8|CT|tag16. AAD đến hếtname. length8 bắt buộc bằng phần còn lại. Baseline overhead302+M. Mỗi gói khóa/IV mới bằngSecureRandom;seed42 chỉ cho dữ liệu benchmark.']),
 ('5. Thực nghiệm và metric',['72 phép đo:letters/repeated-text/random-bytes ×4size ×2mode ×3lần. Warmup5/mode100KiB;đổi thứ tự. Đo wallclock toàn pack/unpack,không tính sinh cặpRSA,mạng/đĩa và so correctness.','Lưu raw,mean,sampleSD,CI95thăm dòt(df2),throughputMiB/s,size,overhead,correctness và negative. n3 cùngJVM còn yếu,không chọn lần nhanh nhất,không tuyên bố vượt paper. Bộ evidence mới nằm artifacts/run-<UTC>. Config processor/maxheap không phải số đo tiêu thụ CPU/RAM.']),
 ('6. Giới hạn và threat model',['Giả định publickey đáng tin,privatekey không lộ và endpoint tin cậy. Đối thủ đọc/sửa/cắt/nối gói hoặc sai key. Tên tệp hiện rõ nhưng được xác thực. Web SSP2 xác thực chữ ký Alice theo public key đã cấu hình, lưu keystore lâu dài. Chưa chống replay hoặc forward secrecy.','Web HTTP chỉ bind loopback, có chế độ combined/sender/receiver; private key được mở vào RAM khi dùng. Chỉ tệp công khai/giả lập. Có giới hạn giải nén 20 MiB và cache TTL; chưa có VM/container evidence hoặc streaming đầy đủ. Prototype chưa phải dịch vụ production.']),
 ('7. Phạm vi giữa kỳ và việc sau',['Đã có nguyên mẫu,nguồn tham chiếu đúng tham số,test gói/negative,validatorNIST cục bộ và benchmark sơ bộ. Chưa tự nhận báo cáo cuối kỳ đủ20–30trang,video,bản dịch hoặc chứng nhận.','Sau giữa kỳ:tăng lần/process độc lập,đo tài nguyên,dữ liệu công khai thực,môi trường cô lập và quản lý khóa. Hướng phát triển: ứng dụng desktop cục bộ chỉ chuyển gói đã bảo vệ; hoặc hệ thống nội bộ có server với HTTPS, xác thực và phân quyền nếu dữ liệu đi qua mạng.'])])
 print('Generated Word documents for exact-configuration NIST vectors')
if __name__=='__main__':main()
